public static class Baseline { public static long Run(int[] values, int threshold) { List<int> selected = new List<int>(values.Length); for (int i = 0; i < values.Length; i++) { if ((long)values[i] * values[i] > (long)threshold * threshold) { selected.Add(values[i]); } } int[] selectedArray = selected.ToArray(); long sum = 0; foreach (int value in selectedArray) { sum += (long)value * value; } return sum; } }